-- Show all tables in the requested order, then the remaining lookup tables.
SELECT 'Tourist Spot Table' AS Table_Name;
SELECT * FROM Tourist_Spot;

SELECT 'Hotel Table' AS Table_Name;
SELECT * FROM Hotel;

SELECT 'Hotel Room Type Table' AS Table_Name;
SELECT * FROM Hotel_Room_Type;
SELECT 'Package Table' AS Table_Name;
SELECT * FROM Package;

SELECT 'Bus Table' AS Table_Name;
SELECT * FROM Bus;

SELECT 'Driver Table' AS Table_Name;
SELECT * FROM Driver;

SELECT 'Tour Guide Table' AS Table_Name;
SELECT * FROM Tour_Guide;

SELECT 'Bus Seat Table' AS Table_Name;
SELECT * FROM Bus_Seat;

SELECT 'Customer Table' AS Table_Name;
SELECT * FROM Customer;

SELECT 'Booking Table' AS Table_Name;
SELECT * FROM Booking;

SELECT 'Available Seat Table' AS Table_Name;

SELECT Bus_no, Seat_No
FROM Bus_Seat
WHERE Seat_No NOT IN (
    SELECT Seat_No
    FROM Booking
    WHERE Booking.Bus_no = Bus_Seat.Bus_no
      AND (Status = 'Confirmed' OR Status = 'Pending')
)
ORDER BY Bus_no, Seat_No;

-- 1. Show all customer details together with all details of the customer's package
SELECT *
FROM Customer, Package
WHERE Customer.Customer_ID = 13201
  AND Customer.Package_ID = Package.Package_ID;


-- 2. Show confirmed seats of Bus 400 along with customer details
SELECT *
FROM Customer, Booking
WHERE Customer.Customer_ID = Booking.Customer_ID
  AND Booking.Bus_no = 400
  AND Booking.Status = 'Confirmed'
ORDER BY Booking.Seat_No;


-- 3. (Available seats of Bus 400) ekhane sudu canceled seat dekhache naki available sob seat dekhache bujte parchi na
-- Confirmed and Pending seats are excluded; Cancelled seats are shown as available.


SELECT Bus_no, Seat_No, Status
FROM Booking
WHERE Bus_no = 400
  AND Status = 'Cancelled';



-- 4. Count the available seats of Bus 401 using COUNT
SELECT COUNT(Seat_No) AS Available_Seat_Count
FROM Bus_Seat
WHERE Bus_no = 401
  AND Seat_No NOT IN (
      SELECT Seat_No
      FROM Booking
      WHERE Bus_no = 401
        AND (Status = 'Confirmed' OR Status = 'Pending')
  );


-- 5. AND: Show customers of Package 201, excluding Customer 13201
SELECT *
FROM Customer
WHERE Package_ID = 201
  AND Customer_ID != 13201;


-- 6. Same condition as above, written using NOT
SELECT *
FROM Customer
WHERE Package_ID = 201
  AND NOT Customer_ID = 13201;


-- 7. Show only the details of Customer 13201
SELECT *
FROM Customer
WHERE Customer_ID = 13201;


-- 8. OR: Show Non-AC buses or Bus 401
SELECT *
FROM Bus
WHERE Bus_Type = 'Non-AC'
   OR Bus_no = 401;


-- 9. Add up the price of all packages using SUM
SELECT SUM(Price) AS Total_Package_Price
FROM Package;


-- 10. Add up the package price of all Confirmed bookings
SELECT SUM(Package.Price) AS Total_Confirmed_Booking_Price
FROM Package, Booking
WHERE Package.Package_ID = Booking.Package_ID
  AND Booking.Status = 'Confirmed';


-- 11. Sort packages by price, lowest to highest
SELECT *
FROM Package
ORDER BY Price ASC;


-- 12. Sort customers by name alphabetically
SELECT *
FROM Customer
ORDER BY Customer_Name ASC;


-- 13. Sort packages by price, highest to lowest
SELECT *
FROM Package
ORDER BY Price DESC;


-- 14. Add a temporary note column to Bus to demonstrate ALTER TABLE and ADD COLUMN
ALTER TABLE Bus ADD COLUMN Practice_Note VARCHAR(100);


-- 15. Remove the temporary note column from Bus after the ALTER TABLE demonstration
ALTER TABLE Bus DROP COLUMN Practice_Note;




-- 16. Update Customer 13201's age to 30
UPDATE Customer
SET Customer_Age = 30
WHERE Customer_ID = 13201;


-- 17. SOME: Customers older than at least one customer of Package 201
SELECT *
FROM Customer
WHERE Customer_Age > SOME (
    SELECT Customer_Age
    FROM Customer
    WHERE Package_ID = 201
);


-- 18. ALL: Customers older than every customer of Package 201
SELECT *
FROM Customer
WHERE Customer_Age > ALL (
    SELECT Customer_Age
    FROM Customer
    WHERE Package_ID = 201
);


-- 19. IN: Show customers who booked packages priced above 5000
SELECT *
FROM Customer
WHERE Package_ID IN (
    SELECT Package_ID
    FROM Package
    WHERE Price > 5000
);


-- 20. Count the number of bookings for each bus
SELECT Bus_no, COUNT(Booking_ID) AS Booking_Count
FROM Booking
GROUP BY Bus_no
HAVING COUNT(Booking_ID) > 0;


-- 21. Show packages together with their assigned hotel using an inner join
SELECT Package.Package_ID, Package.Package_Name, Hotel.Hotel_Name, Hotel.Star_Rating
FROM Package
INNER JOIN Hotel
    ON Package.Hotel_Name = Hotel.Hotel_Name;


-- 22. Show every hotel and any package assigned to it using a left join
SELECT Hotel.Hotel_Name, Package.Package_Name
FROM Hotel
LEFT JOIN Package
    ON Hotel.Hotel_Name = Package.Hotel_Name;


-- 23. Calculate the average daily rate across all hotel room types
SELECT AVG(Room_Price_Per_Day) AS Average_Room_Rate_Per_Day
FROM Hotel_Room_Type;


-- 24. Find the highest listed price among all tour packages
SELECT MAX(Price) AS Highest_Package_Price
FROM Package;


-- 25. Find the lowest listed price among all tour packages
SELECT MIN(Price) AS Lowest_Package_Price
FROM Package;
